  /* ------------------------------------------------------------------------ */

  /* Scroll columns individually on mobile */
  @media (max-width: 639px) {
    body.contained-scrolling {
      block-size: 100dvh;
      grid-template-rows: 1fr var(--footer-height);

      #global-container {
        display: grid;
        grid-template-rows: auto 1fr;
        overflow: hidden;
      }

      #main {
        display: grid;
        grid-template-rows: auto auto 1fr;
        overflow: auto;
        padding: 0;
