      const card = document.querySelector('#maybe article##{dom_id(normal_card, :article)}');
      const targetCol = document.querySelector('##{dom_id(triage_column)}');

      card.dispatchEvent(new DragEvent('dragstart', { bubbles: true, cancelable: true, dataTransfer: dt }));
      targetCol.dispatchEvent(new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer: dt }));
      card.dispatchEvent(new DragEvent('dragend', { bubbles: true, cancelable: true, dataTransfer: dt }));
    JS

    # Verify golden card is before normal card in DOM
    golden_before_normal = page.evaluate_script(<<~JS)
      (() => {
        const targetCol = document.querySelector('##{dom_id(triage_column)}');
        const cards = Array.from(targetCol.querySelectorAll('.card'));
        const goldenIdx = cards.findIndex(c => c.id === '#{dom_id(golden_card, :article)}');
        const normalIdx = cards.findIndex(c => c.id === '#{dom_id(normal_card, :article)}');
        return goldenIdx < normalIdx;
      })()
    JS

    assert golden_before_normal, "Golden card should remain before normal card"
  end
end
